{
  "overall_decision": "manual_review",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package fairly shows Kishida's 2022 nuclear-risk choices, including explicit non-proliferation, NPT/CTBT diplomacy, and a mixed security posture. It is heavily official-source driven, but it still balances favorable and adverse readings and keeps inherited constraints visible."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The chapter cleanly presents both anti-aggression diplomacy on Ukraine and the mixed year-end security rewrite. Attribution, contrary evidence, and the defensive-versus-escalatory interpretations are all present."
    },
    {
      "chapter_id": "3B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0038",
          "reason": "This is protest-legitimacy coverage, not direct physical-safety conduct, and it fits 4B better than 3B."
        },
        {
          "evidence_id": "E0039",
          "reason": "This is public-opposition coverage around a state event, not ruler-directed domestic safety or violence control."
        }
      ],
      "material_gaps": [
        {
          "gap": "Stronger direct evidence of Kishida's personal control over police, prosecutors, and protective institutions before and after the Abe assassination.",
          "lenses": [
            "3B.4",
            "3B.9"
          ],
          "best_source_or_query_direction": "Diet records, NPA/internal police reform records, cabinet directives, and contemporaneous accountability reporting.",
          "why_it_matters": "The package currently shows response and reform, but attribution of domestic-safety choices to Kishida is still partly indirect."
        },
        {
          "gap": "More evidence that the church-scandal and protest responses reduced actual harm rather than only improving the public narrative.",
          "lenses": [
            "3B.7",
            "3B.10"
          ],
          "best_source_or_query_direction": "Victim-relief implementation reporting, legal follow-through, and later independent evaluations.",
          "why_it_matters": "Without outcome evidence, the chapter leans on corrective intent more than demonstrated safety improvement."
        }
      ],
      "reason": "The package is fair overall, but it mixes direct safety evidence with legitimacy/protest material and inherited-country baseline reporting. The chapter would be cleaner with more ruler-specific domestic-safety attribution and less reliance on adjacent political-freedom material."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "This is the most complete chapter package. It includes elections, civic space, media constraints, institutional limits, church-fallout, and favorable as well as adverse interpretations. The country-baseline sources are labeled appropriately rather than being overstated as direct Kishida conduct."
    },
    {
      "chapter_id": "5B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "More independent evidence that the 2022 growth/distribution package actually changed household welfare or investment outcomes rather than only announcing them.",
          "lenses": [
            "5B.6",
            "5B.9",
            "5B.10"
          ],
          "best_source_or_query_direction": "Independent budget-execution analysis, household-income distribution data, and post-package evaluations from OECD, IMF, or Japanese statistical releases.",
          "why_it_matters": "The package is strong on intent and design, but the evidence for realized effects is still relatively thin."
        },
        {
          "gap": "Better separation of Kishida's policy effect from BOJ policy, exchange-rate moves, and imported inflation shocks.",
          "lenses": [
            "5B.3",
            "5B.9"
          ],
          "best_source_or_query_direction": "Macro policy analysis that decomposes wage, price, and fiscal effects in 2022 Japan.",
          "why_it_matters": "The negative real-wage outcome is real, but attribution is still mixed."
        }
      ],
      "reason": "The chapter is fair and balanced, but it is still more plan- and response-heavy than outcome-heavy. The main remaining weakness is independent evidence of implementation and distributional effect."
    },
    {
      "chapter_id": "6B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Direct year-end outcome evidence for child, fertility, and social-service gains attributable to the 2022 package.",
          "lenses": [
            "6B.2",
            "6B.10"
          ],
          "best_source_or_query_direction": "Japan-specific outcome data on child poverty, fertility treatment uptake, child-care access, and service delivery in 2022-2023.",
          "why_it_matters": "The dossier shows agenda-setting and institutional reform, but not enough measured welfare change."
        },
        {
          "gap": "More subgroup evidence on single-parent households, disabled people, housing insecurity, and food insecurity.",
          "lenses": [
            "6B.3",
            "6B.8"
          ],
          "best_source_or_query_direction": "UNICEF, OECD, Japanese administrative statistics, and independent social-policy evaluations.",
          "why_it_matters": "The chapter needs clearer distributional evidence, not just broad national averages."
        }
      ],
      "reason": "The package covers welfare intent and concrete reforms well, but much of it is still institutional design and crisis relief rather than demonstrated 2022 life-chance improvement."
    },
    {
      "chapter_id": "7B",
      "decision": "manual_review",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0085",
          "reason": "This is cabinet-party network evidence, not direct traceable Kishida personal self-dealing or private benefit."
        },
        {
          "evidence_id": "E0087",
          "reason": "This is LDP-wide organizational context, not direct Kishida personal conduct."
        },
        {
          "evidence_id": "E0092",
          "reason": "This is a formal cabinet notice about legislation, better treated as remedial context than as direct evidence of Kishida's personal honesty."
        },
        {
          "evidence_id": "E0093",
          "reason": "This is a retrospective government summary, not contemporaneous personal-nexus evidence."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct, traceable evidence of Kishida's own assets, private interests, donor links, or personal self-enrichment is missing.",
          "lenses": [
            "7B.3",
            "7B.4",
            "7B.9"
          ],
          "best_source_or_query_direction": "Asset declarations, donation records, procurement disclosures, and investigative reporting on Kishida's own finances or family business ties.",
          "why_it_matters": "The current evidence mostly describes the surrounding party network, not Kishida's personal honesty or enrichment."
        },
        {
          "gap": "Independent corroboration of the personal claim that Kishida had no links to the former Unification Church and that his vetting instructions were fully followed.",
          "lenses": [
            "7B.1",
            "7B.2",
            "7B.6"
          ],
          "best_source_or_query_direction": "External audits, archival reporting, and follow-up investigations into ministerial and LDP appointments.",
          "why_it_matters": "Without personal-nexus corroboration, the chapter risks collapsing into party-scandal context rather than ruler integrity."
        }
      ],
      "reason": "This is the weakest chapter fit. The dossier is dominated by party-level church ties and corrective response, while direct Kishida-specific honesty or self-dealing evidence remains thin. That is not yet clean enough for a confident non-review disposition."
    },
    {
      "chapter_id": "8B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "More independent evidence on whether the 2022 startup, digital, and green-growth agenda actually produced measurable execution, not just planning.",
          "lenses": [
            "8B.2",
            "8B.6",
            "8B.7"
          ],
          "best_source_or_query_direction": "Budget execution data, implementation reviews, and post-2022 independent evaluations of the startup and new-capitalism agenda.",
          "why_it_matters": "The dossier is strong on strategy and coordination but thinner on realized program progress outside a few concrete items."
        },
        {
          "gap": "Clearer separation of Kishida's own execution from external shocks and inherited macro conditions when judging the economic package and wage trajectory.",
          "lenses": [
            "8B.7",
            "8B.9",
            "8B.10"
          ],
          "best_source_or_query_direction": "OECD/IMF decompositions, labor-market analyses, and Japan statistical releases on wages and prices.",
          "why_it_matters": "The chapter needs sharper attribution for both gains and misses."
        }
      ],
      "reason": "The program-to-action chain is solid, but outcome evidence remains patchier than the planning and coordination evidence. It is usable, but not fully closed."
    }
  ]
}
